<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateSnippet\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\Retrieve\TemplateSnippetRetrieveUsecase;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\Retrieve\TemplateSnippetRetrieveResult;

class TemplateSnippetRetrieveController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly TemplateSnippetRetrieveUsecase $retrieveUsecase,
    ) {
    }
    #[OA\Get(
        path: "/api/document/template-snippet{uid}",
        tags: ["Template snippet"],
        description:"Create",
        parameters: [
               new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
          ],
        responses: [
              new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/TemplateSnippetApiDTO")),
              new OA\Response(response: 404, description: "Not found"),
          ]
    )]
    public function retrieve(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Retrieve Template snippet");
        $span = $this->startSpan("Retrieve Template snippet");
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $result = $this->retrieveUsecase->retrieve($uid);
            $value = $this->mapTemplateSnippet($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
                  ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapTemplateSnippet(ServerRequestInterface $request, TemplateSnippetRetrieveResult $value): TemplateSnippetApiDTO
    {
        $this->logDebug("Map entity to output dto for Template snippet");
        $span = $this->startSpan("Map entity to output dto for Template snippet");
        try {
            $tenant = $value->getTenant();
            $dto = new TemplateSnippetApiDTO();
            $dto->uid = $value->getUid();
            $dto->code = $value->getCode();
            $dto->tenant = $tenant ? ['$ref' => $tenant->uid()] : null;
            $dto->contentHtml = $value->getContentHtml();
            $dto->enabled = $value->isEnabled();
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
